CREATE TABLE IF NOT EXISTS auth_identites_externes (issuer TEXT NOT NULL, sujet TEXT NOT NULL, userId TEXT NOT NULL, tenantId TEXT,
  annuaireId TEXT, lieeLe TEXT NOT NULL, lieePar TEXT NOT NULL, preuve TEXT NOT NULL, derniereConnexion TEXT, PRIMARY KEY (issuer, sujet));
CREATE INDEX IF NOT EXISTS idx_auth_identites_externes_user ON auth_identites_externes (userId);
CREATE TABLE IF NOT EXISTS auth_demandes_liaison (id TEXT PRIMARY KEY, issuer TEXT NOT NULL, sujet TEXT NOT NULL, courriel TEXT NOT NULL,
  tenantId TEXT NOT NULL, annuaireId TEXT, compteId TEXT NOT NULL, statut TEXT NOT NULL, creeLe TEXT NOT NULL, decideeLe TEXT, decideePar TEXT);
CREATE INDEX IF NOT EXISTS idx_auth_demandes_liaison_attente ON auth_demandes_liaison (tenantId, statut);
